// Recharts v3 exposes formatter values as a broad union (and sometimes undefined).
// These wrappers preserve the runtime primitives while keeping the legacy chart
// callbacks compatible with the upgraded library types.
/* eslint-disable @typescript-eslint/no-explicit-any */
type BroadChartFormatter = (...args: any[]) => React.ReactNode;
type ChartTooltipProps = Omit<
  React.ComponentProps<typeof RechartsTooltip>,
  "formatter" | "labelFormatter"
> & {
  formatter?: BroadChartFormatter;
  labelFormatter?: BroadChartFormatter;
};
function Tooltip(props: ChartTooltipProps) {
  return (
    <RechartsTooltip
      {...(props as React.ComponentProps<typeof RechartsTooltip>)}
    />
  );
}
type ChartLabelListProps = Omit<
  React.ComponentProps<typeof RechartsLabelList>,
  "formatter"
> & { formatter?: BroadChartFormatter };
function LabelList(props: ChartLabelListProps) {
  return (
    <RechartsLabelList
      {...(props as React.ComponentProps<typeof RechartsLabelList>)}
    />
  );
}
