function isViewId(value: unknown): value is ViewId {
  return (
    typeof value === "string" &&
    [
      "inicio",
      "ceo",
      "operaciones",
      "ingresos",
      "clientes",
      "bonos",
      "finanzas",
      "equipo",
      "planificacion",
      "archivos",
      "crm",
      "contenido",
      "conocimiento",
      "ajustes",
      "nucleo",
      "editor_production",
      "editor_performance",
    ].includes(value)
  );
}
function readNavigationState(): PersistedNavigation {
  if (typeof window === "undefined") return {};
  try {
    const parsed = JSON.parse(
      window.localStorage.getItem(NAVIGATION_STORAGE_KEY) || "null",
    ) as {
      view?: unknown;
      production?: Record<string, unknown>;
      workspace?: Record<string, unknown>;
      ceo?: Record<string, unknown>;
    } | null;
    const production = parsed?.production;
    const workspace = parsed?.workspace;
    const ceo = parsed?.ceo;
    return {
      view: isViewId(parsed?.view) ? parsed.view : undefined,
      production:
        production && typeof production === "object"
          ? {
              section: [
                "principal",
                "management",
                "history",
                "services",
              ].includes(production.section as string)
                ? (production.section as PersistedProductionNavigation["section"])
                : undefined,
              tab: ["pending", "planned", "history", "corrections"].includes(
                production.tab as string,
              )
                ? (production.tab as PersistedProductionNavigation["tab"])
                : undefined,
              operationsView: ["normal", "calendar"].includes(
                production.operationsView as string,
              )
                ? (production.operationsView as PersistedProductionNavigation["operationsView"])
                : undefined,
              historyPeriod:
                typeof production.historyPeriod === "string" &&
                /^\d{4}-\d{2}$/.test(production.historyPeriod)
                  ? production.historyPeriod
                  : undefined,
              search:
                typeof production.search === "string"
                  ? production.search.slice(0, 120)
                  : undefined,
              sort: [
                "due_asc",
                "due_desc",
                "assigned_desc",
                "client_asc",
              ].includes(production.sort as string)
                ? (production.sort as PersistedProductionNavigation["sort"])
                : undefined,
            }
          : undefined,
      workspace:
        workspace && typeof workspace === "object"
          ? {
              financeTab: [
                "summary",
                "transactions",
                "receivables",
                "bonuses",
                "investments",
                "analytics",
              ].includes(workspace.financeTab as string)
                ? (workspace.financeTab as PersistedWorkspaceNavigation["financeTab"])
                : undefined,
              clientsTab: ["contacts", "rates"].includes(
                workspace.clientsTab as string,
              )
                ? (workspace.clientsTab as PersistedWorkspaceNavigation["clientsTab"])
                : undefined,
            }
          : undefined,
      ceo:
        ceo && typeof ceo === "object"
          ? {
              view: [
                "general",
                "month",
                "evolution",
                "organization",
                "news",
              ].includes(ceo.view as string)
                ? (ceo.view as PersistedCeoNavigation["view"])
                : undefined,
              selectedPeriod:
                typeof ceo.selectedPeriod === "string" &&
                /^\d{4}-\d{2}$/.test(ceo.selectedPeriod)
                  ? ceo.selectedPeriod
                  : undefined,
            }
          : undefined,
    };
  } catch {
    return {};
  }
}
function updateNavigationState(patch: {
  view?: ViewId;
  production?: PersistedProductionNavigation;
  workspace?: PersistedWorkspaceNavigation;
  ceo?: PersistedCeoNavigation;
}) {
  if (typeof window === "undefined") return;
  try {
    const current = readNavigationState();
    const next: PersistedNavigation = {
      ...current,
      ...patch,
      production: patch.production
        ? { ...current.production, ...patch.production }
        : current.production,
      workspace: patch.workspace
        ? { ...current.workspace, ...patch.workspace }
        : current.workspace,
      ceo: patch.ceo ? { ...current.ceo, ...patch.ceo } : current.ceo,
    };
    window.localStorage.setItem(NAVIGATION_STORAGE_KEY, JSON.stringify(next));
  } catch {
    // Navigation persistence is a convenience and must never block the app.
  }
}

