function isEditorialEditor(editor: Editor, users: DirectoryUser[] = []) {
  const role = (editor.role_label || "").trim().toLocaleLowerCase("es-ES");
  if (
    [
      "manager",
      "administrador",
      "admin",
      "owner",
      "fundador",
      "dirección",
      "direccion",
    ].includes(role)
  )
    return false;
  const linkedUser = users.find(
    (user) =>
      user.profile.editor_id === editor.id || user.id === editor.user_id,
  );
  if (linkedUser && ["owner", "admin"].includes(linkedUser.profile.role))
    return false;
  return (
    editor.name.trim().toLocaleLowerCase("es-ES") !==
    "santiago martínez vallejo"
  );
}
function rankingEvidence(entry: ReturnType<typeof scoredPerformance>[number]) {
  const row = entry.row;
  const dated = number(row.on_time_videos) + number(row.late_videos);
  return `Valor ${euro.format(number(row.client_amount))} · ${number(row.approved_without_correction_videos)} a la primera · ${dated ? Math.round((number(row.on_time_videos) * 100) / dated) : 0}% puntual · ${number(row.late_videos)} retrasos · ${number(row.correction_count)} correcciones`;
}
function linked(value: LinkedName) {
  return Array.isArray(value) ? value[0] || null : value;
}
function linkedItem(value: JobItem | JobItem[] | null) {
  return Array.isArray(value) ? value[0] || null : value;
}
function firstFinancial(
  value: JobFinancial | JobFinancial[] | null | undefined,
) {
  return Array.isArray(value) ? value[0] || null : value || null;
}
function jobClient(job: Job) {
  return linked(job.clients)?.name || job.title;
}
function jobEditor(job: Job) {
  const names = (job.job_assignments || [])
    .map((assignment) => linked(assignment.editors)?.name)
    .filter(Boolean);
  return names.length
    ? [...new Set(names)].join(", ")
    : linked(job.editors)?.name || "Sin asignar";
}
function assignmentItemService(item: AssignmentItem) {
  return linkedItem(item.job_items)?.service || "Servicio";
}
function deliveredForJob(job: Job) {
  return (job.job_assignments || [])
    .flatMap((assignment) => assignment.job_assignment_items || [])
    .reduce((sum, item) => sum + number(item.delivered_quantity), 0);
}
function assignedForJob(job: Job) {
  const requested = (job.job_items || []).reduce(
    (sum, item) => sum + number(item.quantity),
    0,
  );
  if (requested > 0) return requested;
  return (job.job_assignments || [])
    .flatMap((assignment) => assignment.job_assignment_items || [])
    .reduce((sum, item) => sum + number(item.assigned_quantity), 0);
}
function reservedForReviewForJob(job: Job) {
  return (job.job_assignments || []).reduce(
    (sum, assignment) =>
      sum +
      (assignment.delivery_submissions || [])
        .filter(
          (submission) =>
            submission.status === "pending_review" ||
            submission.status === "changes_requested",
        )
        .reduce(
          (submissionSum, submission) =>
            submissionSum +
            Math.max(
              0,
              number(submission.quantity) -
                number(submission.approved_quantity),
            ),
          0,
        ),
    0,
  );
}
function fullyDelivered(job: Job) {
  const assigned = assignedForJob(job);
  return assigned > 0 && deliveredForJob(job) >= assigned;
}
function isJobOverdue(job: Job) {
  if (!job.due_on || job.status === "delivered" || job.status === "cancelled")
    return false;
  if (fullyDelivered(job)) return false;
  return job.due_on < madridDateKey();
}
function readyForReviewCount(jobs: Job[]) {
  return jobs.filter(jobNeedsReview).length;
}
function jobNeedsReview(job: Job) {
  return (job.job_assignments || []).some((assignment) =>
    assignment.delivery_submissions?.some((submission) => {
      const hasFolder = Boolean(
        submission.folder_url && isDriveFolderUrl(submission.folder_url),
      );
      const hasFile = Boolean(
        submission.delivery_submission_items?.some(
          (item) => item.url && isDriveFileUrl(item.url),
        ),
      );
      if (!hasFolder && !hasFile) return false;
      return (
        submission.status === "pending_review" ||
        submission.status === "changes_requested" ||
        submission.delivery_submission_items?.some(
          (item) => item.status === "pending_review",
        )
      );
    }),
  );
}
function jobReviewStatus(job: Job) {
  const statuses = (job.job_assignments || []).flatMap((assignment) =>
    (assignment.delivery_submissions || []).flatMap((submission) =>
      (submission.delivery_submission_items || []).length
        ? (submission.delivery_submission_items || []).map(
            (item) => item.status,
          )
        : [submission.status],
    ),
  );
  // A correction request takes priority in the row summary: calling that video
  // "Pendiente de revisar" after feedback exists is misleading for both roles.
  if (statuses.includes("changes_requested")) return "changes_requested";
  if (statuses.includes("pending_review")) return "pending_review";
  return null;
}
function jobHasActiveCorrections(job: Job) {
  return (job.job_assignments || []).some((assignment) =>
    (assignment.delivery_submissions || []).some((submission) =>
      (submission.delivery_submission_items || []).some(
        (item) =>
          item.status === "changes_requested" ||
          (item.delivery_corrections || []).some(
            (correction) => correction.status !== "closed",
          ),
      ),
    ),
  );
}
function deliveryStatusText(status: string) {
  return status === "approved"
    ? "Aprobada"
    : status === "changes_requested"
      ? "Pendiente de corregir"
      : status === "pending_review"
        ? "Pendiente de revisar"
        : "Pendiente";
}
function serviceProgress(job: Job) {
  return (job.job_items || []).map((item) => {
    const delivered = (job.job_assignments || [])
      .flatMap((assignment) => assignment.job_assignment_items || [])
      .filter((assignmentItem) => assignmentItem.job_item_id === item.id)
      .reduce(
        (sum, assignmentItem) =>
          sum + number(assignmentItem.delivered_quantity),
        0,
      );
    return {
      id: item.id,
      service: item.service,
      total: number(item.quantity),
      delivered,
    };
  });
}
function assignmentValue(assignment: JobAssignment, deliveredOnly = false) {
  return (assignment.job_assignment_items || []).reduce(
    (sum, item) =>
      sum +
      number(deliveredOnly ? item.delivered_quantity : item.assigned_quantity) *
        number(item.editor_unit_cost),
    0,
  );
}
type EditorServiceSummary = {
  service: string;
  total: number;
  submitted: number;
  accepted: number;
  reviewing: number;
  unitCost: number;
};
function editorAssignmentsFor(job: Job, editorId: string | null) {
  return (job.job_assignments || []).filter(
    (assignment) => !editorId || assignment.editor_id === editorId,
  );
}
function editorServiceSummaries(job: Job, editorId: string | null) {
  const summaries = new Map<string, EditorServiceSummary>();
  editorAssignmentsFor(job, editorId).forEach((assignment) => {
    (assignment.job_assignment_items || []).forEach((item) => {
      const service = assignmentItemService(item);
      const current = summaries.get(service) || {
        service,
        total: 0,
        submitted: 0,
        accepted: 0,
        reviewing: 0,
        unitCost: number(item.editor_unit_cost),
      };
      const reviewing = (assignment.delivery_submissions || [])
        .filter(
          (submission) =>
            submission.job_item_id === item.job_item_id &&
            (submission.status === "pending_review" ||
              submission.status === "changes_requested"),
        )
        .reduce(
          (sum, submission) =>
            sum +
            Math.max(
              0,
              number(submission.quantity) -
                number(submission.approved_quantity),
            ),
          0,
        );
      current.total += number(item.assigned_quantity);
      current.accepted += number(item.delivered_quantity);
      current.reviewing += reviewing;
      current.submitted += number(item.delivered_quantity) + reviewing;
      current.unitCost = current.unitCost || number(item.editor_unit_cost);
      summaries.set(service, current);
    });
  });
  return [...summaries.values()];
}
function editorJobTotals(job: Job, editorId: string | null) {
  return editorServiceSummaries(job, editorId).reduce(
    (totals, row) => ({
      total: totals.total + row.total,
      submitted: totals.submitted + row.submitted,
      accepted: totals.accepted + row.accepted,
      reviewing: totals.reviewing + row.reviewing,
      pending:
        totals.pending + Math.max(0, row.total - row.accepted - row.reviewing),
      possiblePay: totals.possiblePay + row.total * row.unitCost,
      submittedPay: totals.submittedPay + row.submitted * row.unitCost,
      acceptedPay: totals.acceptedPay + row.accepted * row.unitCost,
    }),
    {
      total: 0,
      submitted: 0,
      accepted: 0,
      reviewing: 0,
      pending: 0,
      possiblePay: 0,
      submittedPay: 0,
      acceptedPay: 0,
    },
  );
}
function addOneMonth(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return value;
  const targetYear = month === 12 ? year + 1 : year;
  const targetMonth = month === 12 ? 1 : month + 1;
  const lastDay = new Date(Date.UTC(targetYear, targetMonth, 0)).getUTCDate();
  return `${targetYear}-${String(targetMonth).padStart(2, "0")}-${String(Math.min(day, lastDay)).padStart(2, "0")}`;
}
// The former singular label remains readable while rates use one canonical service name.
function normalizeService(service: string) {
  return service === "Miniatura" || service === "Miniaturas"
    ? "Miniaturas"
    : service;
}
function findClientRate(
  rates: ClientRate[],
  clientId: string,
  service: string,
) {
  return (
    rates.find(
      (rate) =>
        rate.client_id === clientId &&
        normalizeService(rate.service) === normalizeService(service),
    ) || null
  );
}
function formatDate(value: string | null) {
  if (!value) return "—";
  const parsed = value.includes("T")
    ? new Date(value)
    : new Date(`${value}T12:00:00`);
  return Number.isNaN(parsed.getTime()) ? "—" : dateFormat.format(parsed);
}
function formatDateTime(value: string | null) {
  if (!value) return "—";
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? "—" : dateTimeFormat.format(parsed);
}
function drivePreviewUrl(value: string) {
  const match = value.match(/(?:\/d\/|[?&]id=)([a-zA-Z0-9_-]+)/);
  return match ? `https://drive.google.com/file/d/${match[1]}/preview` : null;
}
function isDriveFolderUrl(value: string) {
  try {
    const url = new URL(value);
    return (
      url.protocol === "https:" &&
      url.hostname === "drive.google.com" &&
      url.pathname.includes("/folders/")
    );
  } catch {
    return false;
  }
}
function isDriveFileUrl(value: string) {
  try {
    const url = new URL(value);
    return (
      url.protocol === "https:" &&
      url.hostname === "drive.google.com" &&
      !url.pathname.includes("/folders/") &&
      (url.pathname.includes("/file/") ||
        url.pathname.includes("/open") ||
        url.searchParams.has("id"))
    );
  } catch {
    return false;
  }
}
function roleName(role: PortalRole) {
  return role === "Dirección" ? "Administrador" : role;
}
// Deliveries belong to an assignment, not directly to an assignment item.
// Load the real relation once and attach each delivery to its matching service.
function hydrateDeliveryItems(rows: Job[]) {
  return rows.map((job) => ({
    ...job,
    job_assignments: (job.job_assignments || []).map((assignment) => ({
      ...assignment,
      job_assignment_items: (assignment.job_assignment_items || []).map(
        (item) => ({
          ...item,
          job_deliveries: (assignment.job_deliveries || []).filter(
            (delivery) => delivery.job_item_id === item.job_item_id,
          ),
        }),
      ),
    })),
  }));
}
