    const pendingScopes = new Set<string>();
    const scheduleRefresh = (scope: string) => {
      pendingScopes.add(scope);
      if (pendingRefresh !== null) window.clearTimeout(pendingRefresh);
      pendingRefresh = window.setTimeout(() => {
        pendingRefresh = null;
        const scopes = [...pendingScopes];
        pendingScopes.clear();
        void refresh(scopes);
      }, 600);
    };
    const channel = supabase.channel(
      `negodigi-workspace-${profile.organization_id}`,
    );
    const tableScopes: Record<string, string> = {
      jobs: "production",
      job_items: "production",
      job_assignments: "production",
      job_assignment_items: "production",
      job_deliveries: "production",
      delivery_submissions: "production",
      delivery_submission_items: "production",
      delivery_corrections: "production",
      editor_activity_events: "activity",
      editor_planning_blocks: "planning",
      client_publication_slots: "production",
      editor_work_schedules: "activity",
      editor_financial_goals: "goals",
      editor_daily_ranking_points: "ranking",
      editor_weekly_recognitions: "ranking",
      editor_communication_reviews: "ranking",
      editor_ranking_settings: "ranking",
      editor_reward_settings: "ranking",
      editor_monthly_rankings: "ranking",
      editor_monthly_awards: "ranking",
      team_hiring_leads: "hiring",
      notifications: "notifications",
      bonus_accounts: "bonuses",
      bonus_movements: "bonuses",
      profiles: "directory",
      editors: "directory",
      team_announcements: "announcements",
    };
    Object.entries(tableScopes).forEach(([table, scope]) => {
      channel.on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table,
          filter: `organization_id=eq.${profile.organization_id}`,
        },
        () => scheduleRefresh(scope),
      );
    });
