  const patchLoadedDeliveryItem = React.useCallback(
    (
      itemId: string,
      updateItem: (item: DeliverySubmissionItem) => DeliverySubmissionItem,
    ) => {
      setJobs((current) =>
        current.map((job) => {
          let jobChanged = false;
          const assignments = (job.job_assignments || []).map((assignment) => {
            let assignmentChanged = false;
            const submissions = (assignment.delivery_submissions || []).map(
              (submission) => {
                let submissionChanged = false;
                const items = (submission.delivery_submission_items || []).map(
                  (item) => {
                    if (item.id !== itemId) return item;
                    jobChanged = true;
                    assignmentChanged = true;
                    submissionChanged = true;
                    return updateItem(item);
                  },
                );
                return submissionChanged
                  ? { ...submission, delivery_submission_items: items }
                  : submission;
              },
            );
            return assignmentChanged
              ? { ...assignment, delivery_submissions: submissions }
              : assignment;
          });
          return jobChanged ? { ...job, job_assignments: assignments } : job;
        }),
      );
    },
    [],
  );
  const patchLoadedCorrection = React.useCallback(
    (
      correctionId: string,
      updateCorrectionRow: (
        correction: DeliveryCorrection,
      ) => DeliveryCorrection | null,
    ) => {
      setJobs((current) =>
        current.map((job) => {
          let jobChanged = false;
          const assignments = (job.job_assignments || []).map((assignment) => {
            let assignmentChanged = false;
            const submissions = (assignment.delivery_submissions || []).map(
              (submission) => {
                let submissionChanged = false;
                const items = (submission.delivery_submission_items || []).map(
                  (item) => {
                    const corrections = item.delivery_corrections || [];
                    if (
                      !corrections.some(
                        (correction) => correction.id === correctionId,
                      )
                    ) {
                      return item;
                    }
                    const nextCorrections = corrections.flatMap(
                      (correction) => {
                        if (correction.id !== correctionId) return [correction];
                        const next = updateCorrectionRow(correction);
                        return next ? [next] : [];
                      },
                    );
                    jobChanged = true;
                    assignmentChanged = true;
                    submissionChanged = true;
                    return { ...item, delivery_corrections: nextCorrections };
                  },
                );
                return submissionChanged
                  ? { ...submission, delivery_submission_items: items }
                  : submission;
              },
            );
            return assignmentChanged
              ? { ...assignment, delivery_submissions: submissions }
              : assignment;
          });
          return jobChanged ? { ...job, job_assignments: assignments } : job;
        }),
      );
    },
    [],
  );
