  async function deleteJob(id: string) {
    if (blockPreviewMutation()) return false;
    if (!profile || !isAdministrativeRole(profile.role)) return false;
    const job = jobs.find((row) => row.id === id);
    if (!job || !["pending", "planned"].includes(job.status)) {
      setError(
        "Solo se pueden eliminar trabajos activos desde Pendientes o Previstos.",
      );
      return false;
    }
    const filePathsByBucket = new Map<string, string[]>();
    (job.files || []).forEach((file) => {
      filePathsByBucket.set(file.storage_bucket, [
        ...(filePathsByBucket.get(file.storage_bucket) || []),
        file.storage_path,
      ]);
    });
    const { error: deleteError } = await supabase
      .from("jobs")
      .delete()
      .eq("id", id)
      .in("status", ["pending", "planned"])
      .select("id")
      .single();
    if (deleteError) {
      setError(`No se pudo eliminar el trabajo: ${deleteError.message}`);
      return false;
    }
    // Database rows are gone atomically. Remove linked storage objects too;
    // cleanup failure must not recreate the deleted work item.
    await Promise.all(
      [...filePathsByBucket.entries()].map(async ([bucket, paths]) => {
        if (paths.length) await supabase.storage.from(bucket).remove(paths);
      }),
    );
    setNotice("Trabajo eliminado permanentemente.");
    await refresh("production");
    return true;
  }
