  async function submitDelivery(input: {
    assignmentId: string;
    jobItemId: string;
    quantity: number;
    videos: { label: string; url: string }[];
  }) {
    if (blockPreviewMutation()) return false;
    if (!profile || input.quantity <= 0) return false;
    setNotice("");
    const videos = input.videos.filter(
      (video) => video.label.trim() && video.url.trim(),
    );
    if (
      videos.length !== input.quantity ||
      videos.some((video) => !isDriveFileUrl(video.url.trim()))
    ) {
      setError(
        `Añade exactamente ${input.quantity} enlaces de archivos de Drive.`,
      );
      return false;
    }
    const parent = jobs.find((row) =>
      (row.job_assignments || []).some(
        (assignment) => assignment.id === input.assignmentId,
      ),
    );
    const assignment = parent?.job_assignments?.find(
      (row) => row.id === input.assignmentId,
    );
    const assignmentItem = assignment?.job_assignment_items?.find(
      (item) => item.job_item_id === input.jobItemId,
    );
    const remaining = assignmentItem
      ? number(assignmentItem.assigned_quantity) -
        number(assignmentItem.delivered_quantity) -
        (assignment?.delivery_submissions || [])
          .filter(
            (submission) =>
              submission.job_item_id === input.jobItemId &&
              (submission.status === "pending_review" ||
                submission.status === "changes_requested"),
          )
          .reduce(
            (sum, submission) =>
              sum +
              Math.max(
                0,
                number(submission.quantity) -
                  number(submission.approved_quantity),
              ),
            0,
          )
      : 0;
    if (
      !parent ||
      !assignment ||
      !assignmentItem ||
      input.quantity > remaining
    ) {
      setError("La cantidad supera las unidades pendientes de este trabajo.");
      return false;
    }
    const { data: submissionId, error: submissionError } = await supabase.rpc(
      "submit_delivery_items",
      {
        target_assignment: input.assignmentId,
        target_job_item: input.jobItemId,
        delivery_items: videos,
        acting_as_user_id:
          previewRole === "Editor" ? previewSubject?.userId || null : null,
      },
    );
    if (submissionError) {
      setError(
        submissionError?.message ||
          "No se pudo crear la entrega para revisión.",
      );
      await refresh("production");
      return false;
    }
    if (previewRole === "Editor")
      void recordPreviewAction(
        "submit_delivery_as_editor",
        "delivery_submission",
        submissionId || null,
        { assignment_id: input.assignmentId },
      );
    await refresh("production");
    setNotice(
      "Entrega enviada a revisión. El panel de editor se mantiene abierto.",
    );
    return true;
  }
  async function createCorrection(itemId: string, body: string) {
    if (blockPreviewMutation()) return null;
    if (
      !profile ||
      (profile.role !== "owner" && profile.role !== "admin") ||
      !body.trim()
    )
      return null;
    const user = (await supabase.auth.getUser()).data.user;
    const { data, error } = await supabase
      .from("delivery_corrections")
      .insert({
        organization_id: profile.organization_id,
        submission_item_id: itemId,
        created_by: user?.id || null,
        body: body.trim(),
        status: "pending",
      })
      .select(
        "id,submission_item_id,created_by,body,status,editor_response,editor_completed,responded_at,reviewed_at,closed_at,created_at,updated_at",
      )
      .single();
    if (error || !data) {
      setError(error?.message || "No se pudo crear la corrección.");
      return null;
    }
    // Adding an instruction reopens this logical video for the editor without
    // creating another delivery, job or payment record.
    const { data: item } = await supabase
      .from("delivery_submission_items")
      .select("submission_id")
      .eq("id", itemId)
      .maybeSingle();
    await supabase
      .from("delivery_submission_items")
      .update({ status: "changes_requested", reviewed_at: null })
      .eq("id", itemId);
    if (item?.submission_id) {
      const { data: submission } = await supabase
        .from("delivery_submissions")
        .select("assignment_id,job_id")
        .eq("id", item.submission_id)
        .maybeSingle();
      await supabase
        .from("delivery_submissions")
        .update({
          status: "changes_requested",
          review_notes: null,
          reviewed_by: null,
          reviewed_at: null,
        })
        .eq("id", item.submission_id);
      if (submission) {
        await supabase
          .from("job_assignments")
          .update({ status: "in_progress" })
          .eq("id", submission.assignment_id);
        await supabase
          .from("jobs")
          .update({ status: "pending", delivered_on: null })
          .eq("id", submission.job_id);
      }
    }
    patchLoadedDeliveryItem(itemId, (currentItem) => ({
      ...currentItem,
      status: "changes_requested",
      reviewed_at: null,
      delivery_corrections: [
        ...(currentItem.delivery_corrections || []),
        data as DeliveryCorrection,
      ],
    }));
    void refresh("production");
    return data as DeliveryCorrection;
  }
  async function updateCorrection(
    correctionId: string,
    changes: { body?: string; status?: string },
  ) {
    if (blockPreviewMutation()) return false;
    if (!profile || (profile.role !== "owner" && profile.role !== "admin"))
      return false;
    const update: { body?: string; status?: string } = {};
    if (changes.body !== undefined) {
      if (!changes.body.trim()) return false;
      update.body = changes.body.trim();
    }
    if (changes.status !== undefined) update.status = changes.status;
    const { error } = await supabase
      .from("delivery_corrections")
      .update(update)
      .eq("id", correctionId);
    if (error) {
      setError(error.message);
      return false;
    }
    const updatedAt = new Date().toISOString();
    patchLoadedCorrection(correctionId, (currentCorrection) => ({
      ...currentCorrection,
      ...update,
      updated_at: updatedAt,
    }));
    void refresh("production");
    return true;
  }
  async function deleteCorrection(correctionId: string) {
    if (blockPreviewMutation()) return false;
    if (!profile || (profile.role !== "owner" && profile.role !== "admin"))
      return false;
    const { data: attachments } = await supabase
      .from("files")
      .select("id,storage_bucket,storage_path")
      .eq("correction_id", correctionId);
    for (const file of attachments || []) {
      await supabase.storage
        .from(file.storage_bucket)
        .remove([file.storage_path]);
    }
    if ((attachments || []).length)
      await supabase.from("files").delete().eq("correction_id", correctionId);
    const { error } = await supabase
      .from("delivery_corrections")
      .delete()
      .eq("id", correctionId);
    if (error) {
      setError(error.message);
      return false;
    }
    patchLoadedCorrection(correctionId, () => null);
    void refresh("production");
    return true;
  }
  async function respondCorrection(correctionId: string, response: string) {
    if (blockPreviewMutation()) return false;
    if (!profile || !response.trim()) return false;
    const { data: correction, error: lookupError } = await supabase
      .from("delivery_corrections")
      .select("status")
      .eq("id", correctionId)
      .single();
    if (lookupError || !correction) {
      setError(lookupError?.message || "No se encontró la corrección.");
      return false;
    }
    const { error } = await supabase
      .from("delivery_corrections")
      .update({
        editor_response: response.trim(),
        responded_at: new Date().toISOString(),
        status: correction.status === "closed" ? "closed" : "responded",
      })
      .eq("id", correctionId);
    if (error) {
      setError(error.message);
      return false;
    }
    const respondedAt = new Date().toISOString();
    patchLoadedCorrection(correctionId, (currentCorrection) => ({
      ...currentCorrection,
      editor_response: response.trim(),
      responded_at: respondedAt,
      status: currentCorrection.status === "closed" ? "closed" : "responded",
      updated_at: respondedAt,
    }));
    if (previewRole === "Editor")
      void recordPreviewAction(
        "respond_correction_as_editor",
        "delivery_correction",
        correctionId,
      );
    void refresh("production");
    return true;
  }
