  async function reviewDeliverySubmission(
    submissionId: string,
    status: "approved" | "changes_requested",
    reviewNotes: string,
    itemId?: string,
  ) {
    if (blockPreviewMutation()) return false;
    if (!profile || (profile.role !== "owner" && profile.role !== "admin"))
      return false;
    if (itemId) {
      const { error } = await supabase.rpc("review_delivery_item", {
        target_submission: submissionId,
        target_item: itemId,
        decision: status,
      });
      if (error) {
        setError(error.message);
        return false;
      }
      await refresh("production");
      setNotice(
        status === "approved"
          ? "Vídeo aprobado y registrado en Historial."
          : "Correcciones solicitadas para este vídeo.",
      );
      return true;
    }
    const { data: auth } = await supabase.auth.getUser();
    const { data: submission, error: submissionLookupError } = await supabase
      .from("delivery_submissions")
      .select(
        "assignment_id,job_id,job_item_id,quantity,approved_quantity,status",
      )
      .eq("id", submissionId)
      .single();
    if (submissionLookupError || !submission) {
      setError(submissionLookupError?.message || "No se encontró la entrega.");
      return false;
    }
    const reviewedAt = new Date().toISOString();
    if (itemId) {
      const { data: item, error: itemLookupError } = await supabase
        .from("delivery_submission_items")
        .select("id,status")
        .eq("id", itemId)
        .eq("submission_id", submissionId)
        .single();
      if (itemLookupError || !item) {
        setError(itemLookupError?.message || "No se encontró el vídeo.");
        return false;
      }
      const { error: itemError } = await supabase
        .from("delivery_submission_items")
        .update({
          status,
          correction_notes: reviewNotes.trim() || null,
          reviewed_at: reviewedAt,
          updated_at: reviewedAt,
        })
        .eq("id", itemId)
        .eq("submission_id", submissionId);
      if (itemError) {
        setError(itemError.message);
        return false;
      }
      if (status === "approved" && item.status !== "approved") {
        await supabase
          .from("delivery_corrections")
          .update({
            status: "closed",
            reviewed_at: reviewedAt,
            closed_at: reviewedAt,
          })
          .eq("submission_item_id", itemId)
          .neq("status", "closed");
        const { data: correctionRows } = await supabase
          .from("delivery_corrections")
          .select("id")
          .eq("submission_item_id", itemId);
        const correctionIds = (correctionRows || []).map((row) => row.id);
        const { data: temporaryFiles } = correctionIds.length
          ? await supabase
              .from("files")
              .select("id,storage_bucket,storage_path")
              .eq("job_id", submission.job_id)
              .eq("file_kind", "correction_attachment")
              .in("correction_id", correctionIds)
          : await supabase
              .from("files")
              .select("id,storage_bucket,storage_path")
              .eq("job_id", submission.job_id)
              .eq("file_kind", "correction_attachment")
              .like("storage_path", `%/${itemId}/%`);
        for (const file of temporaryFiles || []) {
          await supabase.storage
            .from(file.storage_bucket)
            .remove([file.storage_path]);
          await supabase.from("files").delete().eq("id", file.id);
        }
        const { error: deliveryError } = await supabase
          .from("job_deliveries")
          .upsert(
            {
              organization_id: profile.organization_id,
              assignment_id: submission.assignment_id,
              job_item_id: submission.job_item_id,
              quantity: 1,
              delivered_on: madridDateKey(),
              notes: "Vídeo aprobado en revisión",
              submission_item_id: itemId,
            },
            { onConflict: "submission_item_id" },
          );
        if (deliveryError) {
          setError(deliveryError.message);
          return false;
        }
        await supabase
          .from("delivery_submissions")
          .update({
            approved_quantity: number(submission.approved_quantity) + 1,
          })
          .eq("id", submissionId);
      } else if (status === "changes_requested") {
        await supabase
          .from("job_assignments")
          .update({ status: "in_progress" })
          .eq("id", submission.assignment_id);
        await supabase
          .from("delivery_submissions")
          .update({
            status: "changes_requested",
            review_notes: reviewNotes.trim() || null,
            reviewed_by: auth.user?.id || null,
            reviewed_at: reviewedAt,
          })
          .eq("id", submissionId);
        await supabase
          .from("jobs")
          .update({ status: "pending", delivered_on: null })
          .eq("id", submission.job_id);
        if (reviewNotes.trim() && item.status !== "changes_requested") {
          await supabase.from("delivery_corrections").insert({
            organization_id: profile.organization_id,
            submission_item_id: itemId,
            created_by: auth.user?.id || null,
            body: reviewNotes.trim(),
            status: "pending",
          });
        }
      }
      const { data: items } = await supabase
        .from("delivery_submission_items")
        .select("status")
        .eq("submission_id", submissionId);
      const approvedCount = (items || []).filter(
        (row) => row.status === "approved",
      ).length;
      await supabase
        .from("delivery_submissions")
        .update({ approved_quantity: approvedCount })
        .eq("id", submissionId);
      if (
        (items || []).length > 0 &&
        (items || []).every((row) => row.status === "approved")
      ) {
        await supabase
          .from("delivery_submissions")
          .update({
            status: "approved",
            reviewed_by: auth.user?.id || null,
            reviewed_at: reviewedAt,
          })
          .eq("id", submissionId);
      }
    } else {
      const { error } = await supabase
        .from("delivery_submissions")
        .update({
          status,
          approved_quantity:
            status === "approved"
              ? submission.quantity
              : submission.approved_quantity,
          review_notes: reviewNotes.trim() || null,
          reviewed_by: auth.user?.id || null,
          reviewed_at: reviewedAt,
        })
        .eq("id", submissionId);
      if (error) {
        setError(error.message);
        return false;
      }
      if (
        status === "approved" &&
        number(submission.approved_quantity) < number(submission.quantity)
      ) {
        const { error: deliveryError } = await supabase
          .from("job_deliveries")
          .insert({
            organization_id: profile.organization_id,
            assignment_id: submission.assignment_id,
            job_item_id: submission.job_item_id,
            quantity:
              number(submission.quantity) -
              number(submission.approved_quantity),
            delivered_on: madridDateKey(),
            notes: "Entrega aprobada en revisión",
          });
        if (deliveryError) {
          setError(deliveryError.message);
          return false;
        }
      } else if (status === "changes_requested") {
        await supabase
          .from("job_assignments")
          .update({ status: "in_progress" })
          .eq("id", submission.assignment_id);
      }
    }
    const { data: assignmentItems } = await supabase
      .from("job_assignment_items")
      .select("assigned_quantity,delivered_quantity")
      .eq("assignment_id", submission.assignment_id);
    const complete =
      (assignmentItems || []).length > 0 &&
      (assignmentItems || []).every(
        (item) =>
          number(item.delivered_quantity) >= number(item.assigned_quantity),
      );
    if (complete) {
      await supabase
        .from("job_assignments")
        .update({ status: "completed" })
        .eq("id", submission.assignment_id);
      const { data: siblings } = await supabase
        .from("job_assignments")
        .select("status")
        .eq("job_id", submission.job_id);
      if (
        (siblings || []).length > 0 &&
        (siblings || []).every((row) =>
          ["completed", "cancelled"].includes(row.status),
        )
      ) {
        await supabase
          .from("jobs")
          .update({ status: "delivered", delivered_on: madridDateKey() })
          .eq("id", submission.job_id);
      }
    }
    await refresh("production");
    return true;
  }
  async function addReviewComment(
    itemId: string,
    timestamp: string,
    body: string,
    correctionId?: string,
  ) {
    if (blockPreviewMutation()) return null;
    if (!profile || !body.trim()) return null;
    const value = timestamp.trim();
    let seconds: number | null = null;
    if (value) {
      const parts = value.split(":");
      if (parts.length === 2) {
        const minutes = Number(parts[0]);
        const rest = Number(parts[1].replace(",", "."));
        if (
          Number.isFinite(minutes) &&
          Number.isFinite(rest) &&
          rest >= 0 &&
          rest < 60
        )
          seconds = minutes * 60 + rest;
      } else if (parts.length === 4) {
        const hours = Number(parts[0]);
        const minutes = Number(parts[1]);
        const secs = Number(parts[2]);
        const frames = Number(parts[3]);
        if (
          [hours, minutes, secs, frames].every(Number.isFinite) &&
          minutes >= 0 &&
          minutes < 60 &&
          secs >= 0 &&
          secs < 60 &&
          frames >= 0 &&
          frames < 100
        )
          seconds = hours * 3600 + minutes * 60 + secs + frames / 100;
      } else if (parts.length === 1 && Number.isFinite(Number(value))) {
        seconds = Number(value);
      }
    }
    const { data, error } = await supabase
      .from("delivery_review_comments")
      .insert({
        organization_id: profile.organization_id,
        submission_item_id: itemId,
        author_id: (await supabase.auth.getUser()).data.user?.id || null,
        timestamp_seconds: seconds,
        body: body.trim(),
        correction_id: correctionId || null,
      })
      .select("id,author_id,correction_id,timestamp_seconds,body,created_at")
      .single();
    if (error || !data) {
      setError(error?.message || "No se pudo guardar la respuesta.");
      return null;
    }
    patchLoadedDeliveryItem(itemId, (currentItem) => ({
      ...currentItem,
      delivery_review_comments: [
        ...(currentItem.delivery_review_comments || []),
        data as DeliveryReviewComment,
      ],
    }));
    void refresh("production");
    return data as DeliveryReviewComment;
  }
  async function uploadCorrectionAttachment(
    itemId: string,
    file: File,
    correctionId?: string,
  ) {
    if (blockPreviewMutation()) return null;
    if (!profile || (profile.role !== "owner" && profile.role !== "admin"))
      return null;
    if (!correctionId) {
      setError("Guarda primero la corrección antes de adjuntar un archivo.");
      return null;
    }
    const allowed = [
      "application/pdf",
      "image/png",
      "image/jpeg",
      "image/webp",
      "text/plain",
      "application/msword",
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    ];
    if (!allowed.includes(file.type) || file.size > 10 * 1024 * 1024) {
      setError("Adjunta una imagen, PDF o documento de hasta 10 MB.");
      return null;
    }
    // Resolve the relation from the database, rather than from the review view
    // currently open. That guarantees an uploaded file belongs to this exact
    // correction and video after a live refresh.
    const { data: correction, error: correctionError } = await supabase
      .from("delivery_corrections")
      .select("id,submission_item_id")
      .eq("id", correctionId)
      .eq("submission_item_id", itemId)
      .maybeSingle();
    if (correctionError || !correction) {
      setError(
        correctionError?.message ||
          "No se encontró la corrección para este vídeo.",
      );
      return null;
    }
    const { data: submissionItem, error: itemError } = await supabase
      .from("delivery_submission_items")
      .select("submission_id")
      .eq("id", itemId)
      .single();
    if (itemError || !submissionItem) {
      setError(
        itemError?.message || "No se encontró el vídeo de esta corrección.",
      );
      return null;
    }
    const { data: submission, error: submissionError } = await supabase
      .from("delivery_submissions")
      .select("job_id")
      .eq("id", submissionItem.submission_id)
      .single();
    if (submissionError || !submission) {
      setError(
        submissionError?.message ||
          "No se encontró el trabajo de esta corrección.",
      );
      return null;
    }
    const { data: job, error: jobError } = await supabase
      .from("jobs")
      .select("id,client_id")
      .eq("id", submission.job_id)
      .single();
    if (jobError || !job) {
      setError(jobError?.message || "No se encontró el cliente del trabajo.");
      return null;
    }
    const user = (await supabase.auth.getUser()).data.user;
    if (!user) return null;
    const safeName = file.name.replace(/[^a-zA-Z0-9._-]+/g, "-").slice(-120);
    const bucket = "negodigi-documents";
    const uploadId =
      typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
        ? crypto.randomUUID()
        : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    const path = `${profile.organization_id}/${job.id}/corrections/${correction.id}/${uploadId}-${safeName}`;
    const { error: uploadError } = await supabase.storage
      .from(bucket)
      .upload(path, file, { contentType: file.type, upsert: false });
    if (uploadError) {
      setError(uploadError.message);
      return null;
    }
    const { data: insertedFile, error: fileError } = await supabase
      .from("files")
      .insert({
        organization_id: profile.organization_id,
        job_id: job.id,
        client_id: job.client_id,
        uploaded_by: user.id,
        storage_bucket: bucket,
        storage_path: path,
        file_name: file.name,
        mime_type: file.type,
        size_bytes: file.size,
        file_kind: "correction_attachment",
        correction_id: correction.id,
      })
      .select(
        "id,job_id,client_id,storage_bucket,storage_path,file_name,mime_type,size_bytes,file_kind,correction_id,created_at",
      )
      .single();
    if (fileError || !insertedFile) {
      await supabase.storage.from(bucket).remove([path]);
      setError(fileError?.message || "No se pudo guardar el archivo adjunto.");
      return null;
    }
    appendLoadedCorrectionFile(insertedFile as JobFile);
    void refresh("production");
    setNotice("Adjunto añadido a la corrección.");
    return insertedFile as JobFile;
  }
  async function getAttachmentUrl(
    bucket: string,
    path: string,
    download = false,
  ) {
    const { data, error: signedError } = await supabase.storage
      .from(bucket)
      .createSignedUrl(
        path,
        60 * 60,
        download ? { download: true } : undefined,
      );
    if (signedError) {
      setError(signedError.message);
      return null;
    }
    return data?.signedUrl || null;
  }
