  async function uploadNucleoFile(input: NucleoFileUploadInput) {
    if (blockPreviewMutation()) return null;
    if (!profile || !isAdministrativeRole(profile.role)) return null;
    const allowed = [
      "application/pdf",
      "image/png",
      "image/jpeg",
      "image/webp",
      "application/msword",
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    ];
    if (
      !allowed.includes(input.file.type) ||
      input.file.size > 50 * 1024 * 1024
    ) {
      setError("Adjunta una imagen, PDF o documento de hasta 50 MB.");
      return null;
    }
    if (input.clientId && input.editorId) {
      setError(
        "Un archivo del Núcleo solo puede vincularse a un cliente o a un miembro del equipo.",
      );
      return null;
    }
    const user = (await supabase.auth.getUser()).data.user;
    if (!user) return null;
    const safeName = input.file.name
      .replace(/[^a-zA-Z0-9._-]+/g, "-")
      .slice(-120);
    const uploadId =
      typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
        ? crypto.randomUUID()
        : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    const subjectId =
      input.clientId || input.editorId || profile.organization_id;
    const bucket =
      input.kind === "brand" ? "negodigi-brand" : "negodigi-documents";
    const path = `${profile.organization_id}/${subjectId}/nucleo/${input.kind}/${uploadId}-${safeName}`;
    const { error: uploadError } = await supabase.storage
      .from(bucket)
      .upload(path, input.file, {
        contentType: input.file.type,
        upsert: false,
      });
    if (uploadError) {
      setError(uploadError.message);
      return null;
    }
    const { data: insertedFile, error: fileError } = await supabase
      .from("files")
      .insert({
        organization_id: profile.organization_id,
        job_id: null,
        client_id: input.clientId || null,
        editor_id: input.editorId || null,
        uploaded_by: user.id,
        storage_bucket: bucket,
        storage_path: path,
        file_name: input.file.name,
        mime_type: input.file.type || null,
        size_bytes: input.file.size,
        file_kind: input.kind,
        title: input.title?.trim() || null,
        notes: input.notes?.trim() || null,
        external_url: null,
      })
      .select(
        "id,organization_id,job_id,client_id,editor_id,uploaded_by,storage_bucket,storage_path,file_name,mime_type,size_bytes,file_kind,title,notes,external_url,created_at",
      )
      .single();
    if (fileError || !insertedFile) {
      await supabase.storage.from(bucket).remove([path]);
      setError(
        fileError?.message || "No se pudo registrar el archivo del Núcleo.",
      );
      return null;
    }
    const nextFile = insertedFile as NucleoFile;
    setNucleoFiles((current) => [
      nextFile,
      ...current.filter((row) => row.id !== nextFile.id),
    ]);
    setNotice("Archivo añadido al Núcleo.");
    void refresh("files");
    return nextFile;
  }
  async function deleteNucleoFile(file: NucleoFile) {
    if (blockPreviewMutation()) return false;
    if (!profile || !isAdministrativeRole(profile.role)) return false;
    const { error: storageError } = await supabase.storage
      .from(file.storage_bucket)
      .remove([file.storage_path]);
    if (storageError) {
      setError(storageError.message);
      return false;
    }
    const { error } = await supabase.from("files").delete().eq("id", file.id);
    if (error) {
      setError(error.message);
      return false;
    }
    setNucleoFiles((current) => current.filter((row) => row.id !== file.id));
    setNotice("Archivo eliminado.");
    return true;
  }
