  async function updateTransaction(id: string, input: FinanceTransactionInput) {
    if (blockPreviewMutation()) return;
    if (!profile || !input.concept.trim() || input.amount <= 0) return;
    const original = transactions.find((row) => row.id === id);
    const generatedOccurrence = Boolean(original?.recurrence_parent_id);
    const recurring = generatedOccurrence
      ? false
      : input.movementKind === "subscription";
    const { error: transactionError } = await supabase
      .from("finance_transactions")
      .update({
        transaction_type: input.transactionType,
        amount: input.amount,
        concept: input.concept.trim(),
        category: input.category.trim() || null,
        account: input.account.trim() || null,
        occurred_on: input.occurredOn,
        client_id: input.clientId,
        editor_id: input.editorId,
        notes: input.notes.trim() || null,
        entry_status: input.entryStatus,
        movement_kind: generatedOccurrence
          ? original?.movement_kind || "subscription"
          : input.movementKind,
        is_recurring: recurring,
        recurrence_interval: recurring ? "monthly" : null,
        next_occurrence_on: recurring ? input.nextOccurrenceOn : null,
        recurrence_status: recurring ? "active" : null,
        recurrence_cancelled_on: null,
      })
      .eq("id", id)
      .eq("organization_id", profile.organization_id);
    if (transactionError) {
      setError(transactionError.message);
      return;
    }
    await refresh("finance");
  }
