  async function saveInvestmentLinks(
    investmentId: string,
    input: FinanceInvestmentInput,
  ) {
    const clientIds = [...new Set(input.clientIds.filter(Boolean))];
    const services = [
      ...new Set(
        input.services.map((service) => service.trim()).filter(Boolean),
      ),
    ];
    const [{ error: clientError }, { error: serviceError }] = await Promise.all(
      [
        supabase
          .from("finance_investment_clients")
          .delete()
          .eq("investment_id", investmentId),
        supabase
          .from("finance_investment_services")
          .delete()
          .eq("investment_id", investmentId),
      ],
    );
    if (clientError || serviceError) throw clientError || serviceError;
    if (clientIds.length) {
      const { error } = await supabase
        .from("finance_investment_clients")
        .insert(
          clientIds.map((clientId) => ({
            investment_id: investmentId,
            client_id: clientId,
          })),
        );
      if (error) throw error;
    }
    if (services.length) {
      const { error } = await supabase
        .from("finance_investment_services")
        .insert(
          services.map((serviceName) => ({
            investment_id: investmentId,
            service_name: serviceName,
          })),
        );
      if (error) throw error;
    }
  }
