  async function saveClientRates(
    clientId: string,
    values: Record<
      string,
      {
        client_unit_price: number;
        editor_unit_cost: number;
      }
    >,
  ) {
    if (blockPreviewMutation()) return;
    if (!profile) return;
    for (const service of Object.keys(values)) {
      const current = findClientRate(clientRates, clientId, service);
      const next = values[service];
      const result = current
        ? await supabase.from("client_rates").update(next).eq("id", current.id)
        : await supabase.from("client_rates").insert({
            organization_id: profile.organization_id,
            client_id: clientId,
            service,
            active: true,
            ...next,
          });
      if (result.error) {
        setError(result.error.message);
        return;
      }
    }
    await refresh("clients");
  }
