  async function saveRankingConfiguration(next: RankingSettings) {
    if (blockPreviewMutation()) return false;
    if (!profile) return false;
    const v2Punctuality = number(next.v2_punctuality_weight ?? next.punctuality_weight);
    const v2Communication = number(next.v2_communication_weight ?? 30);
    const v2Quality = number(next.v2_quality_weight ?? next.quality_weight);
    const v2Production = number(next.v2_production_weight ?? next.value_weight);
    const total = v2Punctuality + v2Communication + v2Quality + v2Production;
    if (Math.abs(total - 100) > 0.001) {
      setError("Puntualidad, comunicación, calidad y producción deben sumar exactamente 100 %.");
      return false;
    }
    const { data: auth } = await supabase.auth.getUser();
    if (!auth.user) return false;
    // The live ranking uses four visible criteria. Keep the legacy columns in
    // sync so older database routines cannot reject a valid 100% configuration.
    const normalizedNext: RankingSettings = {
      ...next,
      value_weight: v2Production,
      quality_weight: v2Quality,
      punctuality_weight: v2Punctuality,
      correction_weight: 0,
      late_penalty_points: Math.max(0, number(next.late_penalty_points ?? 2)),
      correction_penalty_points: Math.max(
        0,
        number(next.correction_penalty_points ?? 1),
      ),
      completion_weight: v2Production,
      rework_weight: 0,
      activity_weight: 0,
      commitment_weight: 0,
      min_approved_videos: Math.max(1, number(next.min_approved_videos)),
      v2_punctuality_weight: v2Punctuality,
      v2_communication_weight: v2Communication,
      v2_quality_weight: v2Quality,
      v2_production_weight: v2Production,
      v2_daily_activity_cap: Math.max(0, number(next.v2_daily_activity_cap ?? 5)),
      v2_priority_late_multiplier: Math.max(1, number(next.v2_priority_late_multiplier ?? 1.5)),
      v2_effective_from_period: next.v2_effective_from_period || madridMonthKey(),
    };
    const { error: settingsError } = await supabase
      .from("editor_ranking_settings")
      .upsert(
        {
          ...normalizedNext,
          organization_id: profile.organization_id,
          updated_by: auth.user.id,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "organization_id" },
      );
    if (settingsError) {
      setError(`No se pudo guardar el ranking: ${settingsError.message}`);
      return false;
    }
    setRankingSettings(normalizedNext);
    setNotice("Criterios del ranking guardados.");
    void refresh("ranking");
    return true;
  }
