function OwnerDashboard({
  // Principal intentionally remains a compact decision surface; detailed work lives in its source modules.
  income,
  expenses,
  credit,
  monthly,
  pending,
  overdue,
  manualReceivable,
  excess,
  bonusCount,
  readyForReview,
  onOperations,
  onOpenFinance,
  onOpenCeo,
  onOpenSales,
  onOpenMarketing,
  onOpenNucleo,
  onOpenBonuses,
  onOpenClients,
  onOpenTeam,
  onOpenJob,
  jobs,
  receivables,
  transactions,
  clients,
  bonuses,
  files,
  knowledgeArticles,
  editors,
  editorPayments,
  organizationTasks,
  onSaveOrganizationTask,
  onCompleteOrganizationTask,
  onDeleteOrganizationTask,
  announcements,
  onSaveAnnouncement,
  onDeleteAnnouncement,
  onUploadAnnouncementAsset,
  classicMode,
  onExitClassic,
}: {
  income: number;
  expenses: number;
  credit: number;
  monthly: {
    month: string;
    income: number;
    expense: number;
    net: number;
  }[];
  pending: Job[];
  overdue: number;
  manualReceivable: number;
  excess: number;
  bonusCount: number;
  readyForReview: number;
  onOperations: () => void;
  onOpenFinance: () => void;
  onOpenCeo: () => void;
  onOpenSales: () => void;
  onOpenMarketing: () => void;
  onOpenNucleo: () => void;
  onOpenBonuses: () => void;
  onOpenClients: () => void;
  onOpenTeam: () => void;
  onOpenJob: (jobId: string) => void;
  jobs: Job[];
  receivables: Receivable[];
  transactions: Transaction[];
  clients: Client[];
  bonuses: Bonus[];
  files: NucleoFile[];
  knowledgeArticles: KnowledgeArticle[];
  editors: Editor[];
  editorPayments: EditorPayment[];
  organizationTasks: OrganizationTask[];
  onSaveOrganizationTask: (input: {
    title: string;
    dueOn: string | null;
    priority: OrganizationTask["priority"];
    notes: string;
  }) => Promise<boolean>;
  onCompleteOrganizationTask: (id: string) => Promise<boolean>;
  onDeleteOrganizationTask: (id: string) => Promise<boolean>;
  announcements: TeamAnnouncement[];
  onSaveAnnouncement: (input: {
    id?: string;
    title: string;
    body: string;
    audience: TeamAnnouncement["audience"];
    featuredMonth: string;
    status: TeamAnnouncement["status"];
    priority?: TeamAnnouncement["priority"];
    expiresAt?: string | null;
    linkUrl?: string;
    attachmentUrl?: string;
    videoUrl?: string;
    imageUrl?: string;
  }) => Promise<boolean>;
  onDeleteAnnouncement: (id: string) => Promise<boolean>;
  onUploadAnnouncementAsset: (
    file: File,
    kind: "image" | "attachment" | "video",
  ) => Promise<{ path: string; url: string | null; name: string } | null>;
  classicMode: boolean;
  onExitClassic: () => void;
}) {
  const [section, setSection] = React.useState<
    "principal" | "organization" | "news"
  >("principal");
  if (!classicMode) {
    return (
      <GeneralUniverse
        pendingCount={pending.length}
        onOpenCeo={onOpenCeo}
        onOperations={onOperations}
        onOpenSales={onOpenSales}
        onOpenMarketing={onOpenMarketing}
        onOpenNucleo={onOpenNucleo}
        clients={clients}
        bonuses={bonuses}
        files={files}
        transactions={transactions}
        jobs={jobs}
        knowledgeArticles={knowledgeArticles}
        editors={editors}
        editorPayments={editorPayments}
        onOpenClients={onOpenClients}
        onOpenTeam={onOpenTeam}
        onOpenBonuses={onOpenBonuses}
        onOpenFinance={onOpenFinance}
        onOpenOperations={onOperations}
        onOpenNucleoSearch={onOpenNucleo}
      />
    );
  }
  return (
    <div className="space-y-6">
      {!classicMode && <PageHeading
        eyebrow="General"
        title="Centro de mando"
        description="Una lectura rápida del negocio y un acceso claro a cada área. Sin ruido ni paneles repetidos."
        action={
          <Status tone="green">
            <span className="mr-2 size-1.5 rounded-full bg-emerald-300" />
            Datos consolidados
          </Status>
        }
      />}
      {!classicMode && <section className="dashboard-area-grid grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
        {[
          { label: "CEO", detail: "Dirección, metas y decisiones", icon: Crown, color: "amber", onClick: onOpenCeo },
          { label: "Administración", detail: `${pending.length} trabajos en curso`, icon: ListChecks, color: "sky", onClick: onOperations },
          { label: "Ventas", detail: "CRM, llamadas y cierres", icon: BriefcaseBusiness, color: "violet", onClick: onOpenSales },
          { label: "Marketing", detail: "Contenido y crecimiento", icon: Megaphone, color: "fuchsia", onClick: onOpenMarketing },
          { label: "Núcleo", detail: "Legal, archivos y estrategia", icon: LockKeyhole, color: "emerald", onClick: onOpenNucleo },
        ].map(({ label, detail, icon: Icon, color, onClick }) => <button key={label} type="button" onClick={onClick} className={`dashboard-area-card dashboard-area-${color} group min-h-[154px] rounded-2xl border p-5 text-left`}><div className="relative z-10"><span className="grid size-10 place-items-center rounded-xl bg-black/20"><Icon className="size-[18px]" /></span><p className="mt-7 text-base font-bold">{label}</p><p className="mt-1 text-xs leading-5 opacity-75">{detail}</p><span className="mt-4 inline-flex items-center text-xs font-semibold">Abrir área <ChevronRight className="ml-1 size-3.5 transition-transform group-hover:translate-x-0.5" /></span></div></button>)}
      </section>}
      {!classicMode && <div
        className="inline-flex w-full gap-1 rounded-2xl border border-white/[.07] bg-white/[.02] p-1.5 sm:w-auto"
        role="tablist"
        aria-label="Secciones de Principal"
      >
        <button
          type="button"
          role="tab"
          aria-selected={section === "principal"}
          onClick={() => setSection("principal")}
          className={`flex-1 rounded-xl px-4 py-2.5 text-sm font-semibold transition sm:flex-none ${section === "principal" ? "bg-violet-500 text-white" : "text-slate-400 hover:bg-white/[.04] hover:text-white"}`}
        >
          Resumen
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={section === "organization"}
          onClick={() => setSection("organization")}
          className={`flex flex-1 items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition sm:flex-none ${section === "organization" ? "bg-violet-500 text-white" : "text-slate-400 hover:bg-white/[.04] hover:text-white"}`}
        >
          <ListChecks className="size-4" />
          Organización
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={section === "news"}
          onClick={() => setSection("news")}
          className={`flex flex-1 items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition sm:flex-none ${section === "news" ? "bg-violet-500 text-white" : "text-slate-400 hover:bg-white/[.04] hover:text-white"}`}
        >
          <Megaphone className="size-4" />
          Noticias
        </button>
      </div>}
      {section === "principal" && !classicMode && (
        <>
          <div className="metric-grid">
            <Metric
              label="Ingresos"
              value={euro.format(income)}
              detail="Movimientos reales"
              icon={ArrowUpRight}
              tone="green"
            />
            <Metric
              label="Gastos"
              value={euro.format(expenses)}
              detail="Gasto registrado"
              icon={ArrowDownRight}
              tone="red"
            />
            <Metric
              label="Neto"
              value={euro.format(income - expenses)}
              detail="Ingresos menos gastos"
              icon={TrendingUp}
            />
            <Metric
              label="Crédito disponible"
              value={euro.format(credit)}
              detail={`${bonusCount} bonos activos`}
              icon={WalletCards}
              tone="blue"
            />
          </div>
          <Panel className="command-now-panel overflow-visible p-6">
            <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-[11px] font-bold tracking-[.14em] text-violet-200 uppercase">Plan de hoy</p><h2 className="mt-2 text-xl font-semibold text-white">Tres decisiones, sin saturarte</h2><p className="mt-1 text-sm text-slate-400">Entra directamente al área que necesita una acción real.</p></div><span className="rounded-full border border-white/[.08] bg-black/15 px-3 py-1.5 text-xs text-slate-300">Actualizado con datos reales</span></div>
            <div className="mt-5 grid gap-3 lg:grid-cols-3">
              <button type="button" onClick={onOperations} className="command-now-action command-now-production text-left"><span className="grid size-10 place-items-center rounded-xl bg-sky-300/10 text-sky-200"><ListChecks className="size-[18px]" /></span><p className="mt-5 text-sm font-bold text-white">Operación</p><p className="mt-1 text-xs leading-5 text-slate-400">{pending.length} pendientes · {readyForReview} para revisar · {overdue} fuera de fecha</p><span className="mt-4 inline-flex items-center text-xs font-semibold text-sky-200">Abrir gestión <ChevronRight className="ml-1 size-3.5" /></span></button>
              <button type="button" onClick={onOpenFinance} className="command-now-action command-now-finance text-left"><span className="grid size-10 place-items-center rounded-xl bg-emerald-300/10 text-emerald-200"><ReceiptEuro className="size-[18px]" /></span><p className="mt-5 text-sm font-bold text-white">Caja</p><p className="mt-1 text-xs leading-5 text-slate-400">{euro.format(manualReceivable)} por cobrar{excess > 0 ? ` · ${euro.format(excess)} de exceso` : ""}</p><span className="mt-4 inline-flex items-center text-xs font-semibold text-emerald-200">Abrir finanzas <ChevronRight className="ml-1 size-3.5" /></span></button>
              <button type="button" onClick={onOpenSales} className="command-now-action command-now-sales text-left"><span className="grid size-10 place-items-center rounded-xl bg-violet-300/10 text-violet-200"><BriefcaseBusiness className="size-[18px]" /></span><p className="mt-5 text-sm font-bold text-white">Crecimiento</p><p className="mt-1 text-xs leading-5 text-slate-400">Leads, llamadas y oportunidades comerciales en un solo lugar.</p><span className="mt-4 inline-flex items-center text-xs font-semibold text-violet-200">Abrir ventas <ChevronRight className="ml-1 size-3.5" /></span></button>
            </div>
          </Panel>
          <NegoDigiCore
            clients={clients}
            bonuses={bonuses}
            files={files}
            transactions={transactions}
            jobs={jobs}
            knowledgeArticles={knowledgeArticles}
            editors={editors}
            editorPayments={editorPayments}
            onOpenClients={onOpenClients}
            onOpenTeam={onOpenTeam}
            onOpenBonuses={onOpenBonuses}
            onOpenFinance={onOpenFinance}
            onOpenOperations={onOperations}
            onOpenNucleo={onOpenNucleo}
          />
        </>
      )}
      {classicMode && (
        <>
          <button
            type="button"
            onClick={onExitClassic}
            className="fixed right-5 bottom-5 z-[80] inline-flex items-center gap-2 rounded-2xl border border-violet-200/35 bg-slate-950/95 px-4 py-3 text-sm font-bold text-violet-100 shadow-[0_14px_36px_rgba(0,0,0,.42)] backdrop-blur transition hover:-translate-y-0.5 hover:border-violet-200/60 hover:bg-violet-400/15 focus:outline-none focus:ring-2 focus:ring-violet-300/60"
            aria-label="Volver a la vista nueva"
          >
            <span aria-hidden="true">←</span>
            Volver a la vista nueva
          </button>
          <PageHeading eyebrow="Principal" title="NegoDigi APP" description="Vista clásica de administración. Usa los mismos datos y todas las acciones se guardan en tiempo real." action={<button type="button" onClick={onExitClassic} className="rounded-xl border border-violet-300/25 bg-violet-300/[.08] px-3 py-2 text-xs font-semibold text-violet-100 hover:bg-violet-300/[.14]">Volver a la vista nueva</button>} />
          <Panel className="hidden">
            <div className="flex items-start gap-3">
              <span className="grid size-10 place-items-center rounded-2xl bg-violet-400 text-white">
                <Sparkles className="size-4" />
              </span>
              <div>
                <div className="flex flex-wrap items-center gap-2">
                  <h2 className="font-semibold text-white">Control por IA</h2>
                  <Status>Próximamente</Status>
                </div>
                <p className="mt-1 text-sm text-slate-400">
                  La IA irá al final; primero consolidamos operaciones reales y
                  permisos.
                </p>
              </div>
            </div>
            <div className="mt-5 flex items-center gap-2 rounded-2xl border border-white/[.08] bg-black/20 p-2">
              <input
                disabled
                placeholder="¿Qué quieres que haga?"
                className="h-10 min-w-0 flex-1 bg-transparent px-2 text-sm text-slate-500 outline-none"
              />
              <button
                disabled
                className="h-10 rounded-xl bg-violet-500/50 px-4 text-sm text-violet-100/60"
              >
                Preparar <ChevronRight className="ml-1 inline size-4" />
              </button>
            </div>
          </Panel>
          <div className="metric-grid">
            <Metric
              label="Ingresos"
              value={euro.format(income)}
              detail="Movimientos reales de NegoDigi"
              icon={ArrowUpRight}
              tone="green"
            />
            <Metric
              label="Gastos"
              value={euro.format(expenses)}
              detail="Gasto e inversión unificados"
              icon={ArrowDownRight}
              tone="red"
            />
            <Metric
              label="Neto"
              value={euro.format(income - expenses)}
              detail="Ingresos menos gastos"
              icon={TrendingUp}
            />
            <Metric
              label="Crédito disponible"
              value={euro.format(credit)}
              detail={`${bonusCount} bonos · nunca baja de cero`}
              icon={WalletCards}
              tone="blue"
            />
          </div>
          <div className="grid gap-6 xl:grid-cols-[minmax(0,1.65fr)_minmax(300px,.75fr)]">
            <MonthlyChart data={monthly} />
            <Panel className="p-5">
              <h2 className="font-semibold text-white">Requiere atención</h2>
              <p className="mt-1 text-sm text-slate-500">
                Alertas operativas calculadas
              </p>
              <div className="mt-5 space-y-3">
                <Alert
                  icon={Clock3}
                  tone="red"
                  title={`${overdue} entregas fuera de fecha`}
                  detail="Revisar prioridad y editor asignado"
                />
                <Alert
                  icon={Check}
                  tone="amber"
                  title={`${readyForReview} trabajos listos para revisar`}
                  detail="Los editores han terminado su parte; aprueba desde Producción"
                />
                <Alert
                  icon={WalletCards}
                  tone="amber"
                  title={
                    excess > 0
                      ? "Bonos agotados con exceso"
                      : "Sin excesos de bono"
                  }
                  detail={
                    excess > 0
                      ? `${euro.format(excess)} deben pasar a cobro`
                      : "El crédito no está en negativo"
                  }
                />
                <Alert
                  icon={ReceiptEuro}
                  tone="blue"
                  title="Pagos pendientes"
                  detail={`${euro.format(manualReceivable)} todavía por cobrar`}
                />
              </div>
            </Panel>
          </div>
          <div className="grid gap-6 xl:grid-cols-2">
            <Panel className="p-5">
              <div className="flex items-start justify-between">
                <div>
                  <h2 className="font-semibold text-white">
                    Próximas entregas
                  </h2>
                  <p className="mt-1 text-sm text-slate-500">
                    {pending.length} trabajos abiertos
                  </p>
                </div>
                <button
                  onClick={onOperations}
                  className="text-xs text-violet-300 hover:text-violet-200"
                >
                  Ver todo
                </button>
              </div>
              <div className="mt-3">
                {pending.slice(0, 5).map((job) => (
                  <div
                    key={job.id}
                    className="flex items-center justify-between gap-4 rounded-xl px-2 py-3 hover:bg-white/[.025]"
                  >
                    <div className="min-w-0">
                      <p className="truncate text-sm font-medium text-slate-200">
                        {jobClient(job)}
                      </p>
                      <p className="mt-1 truncate text-xs text-slate-500">
                        {job.title} · {jobEditor(job)}
                      </p>
                    </div>
                    <div className="text-right text-xs text-slate-400">
                      {formatDate(job.due_on)}
                      <p className="mt-1 text-[11px] text-slate-600">
                        {job.job_items?.reduce(
                          (sum, item) => sum + number(item.quantity),
                          0,
                        ) || 0}{" "}
                        piezas
                      </p>
                    </div>
                  </div>
                ))}
                {pending.length === 0 && (
                  <p className="py-10 text-center text-sm text-slate-500">
                    No hay trabajos abiertos.
                  </p>
                )}
              </div>
            </Panel>
            <NetChart data={monthly} />
          </div>
        </>
      )}
      {!classicMode && section === "organization" && (
        <OrganizationWorkspaceV4
          jobs={jobs}
          receivables={receivables}
          transactions={transactions}
          tasks={organizationTasks}
          onSave={onSaveOrganizationTask}
          onComplete={onCompleteOrganizationTask}
          onDelete={onDeleteOrganizationTask}
          onOpenProduction={onOperations}
          onOpenFinance={onOpenFinance}
          onOpenJob={onOpenJob}
        />
      )}
      {!classicMode && section === "news" && (
        <TeamAnnouncementsV2
          announcements={announcements}
          onSave={onSaveAnnouncement}
          onDelete={onDeleteAnnouncement}
          onUploadAsset={onUploadAnnouncementAsset}
        />
      )}
    </div>
  );
}
function OrganizationWorkspace({
  jobs,
  receivables,
  transactions,
  tasks,
  onSave,
  onComplete,
  onDelete,
}: {
  jobs: Job[];
  receivables: Receivable[];
  transactions: Transaction[];
  tasks: OrganizationTask[];
  onSave: (input: {
    title: string;
    dueOn: string | null;
    priority: OrganizationTask["priority"];
    notes: string;
  }) => Promise<boolean>;
  onComplete: (id: string) => Promise<boolean>;
  onDelete: (id: string) => Promise<boolean>;
}) {
  const [title, setTitle] = React.useState("");
  const [dueOn, setDueOn] = React.useState("");
  const [priority, setPriority] =
    React.useState<OrganizationTask["priority"]>("upcoming");
  const [notes, setNotes] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const today = madridDateKey();
  const derived: {
    id: string;
    title: string;
    dueOn: string | null;
    source: string;
    priority: "critical" | "today" | "upcoming";
    manual?: boolean;
  }[] = [
    ...jobs
      .filter((job) => job.status === "pending")
      .map((job) => ({
        id: `job-${job.id}`,
        title: `${jobClient(job)} · ${job.title}`,
        dueOn: job.due_on,
        source: "Producción",
        priority: (isJobOverdue(job)
          ? "critical"
          : job.due_on?.slice(0, 10) === today
            ? "today"
            : "upcoming") as "critical" | "today" | "upcoming",
      })),
    ...receivables
      .filter((row) => row.status !== "paid")
      .map((row) => ({
        id: `pay-${row.id}`,
        title: `Cobrar ${(Array.isArray(row.clients) ? row.clients[0]?.name : row.clients?.name) || "cliente"} · ${euro.format(number(row.amount))}`,
        dueOn: row.started_on,
        source: "Finanzas",
        priority: (row.started_on && row.started_on.slice(0, 10) <= today
          ? "critical"
          : "upcoming") as "critical" | "upcoming",
      })),
    ...transactions
      .filter((row) => row.entry_status === "pending")
      .map((row) => ({
        id: `fin-${row.id}`,
        title: row.concept,
        dueOn: row.next_occurrence_on || row.occurred_on,
        source: "Finanzas",
        priority: "today" as const,
      })),
    ...tasks.map((row) => ({
      id: row.id,
      title: row.title,
      dueOn: row.due_on,
      source: "Calendario",
      priority: row.priority,
      manual: true,
    })),
  ].sort((a, b) => {
    const order: Record<OrganizationTask["priority"], number> = {
      critical: 0,
      today: 1,
      upcoming: 2,
    };
    return (
      order[a.priority] - order[b.priority] ||
      String(a.dueOn || "9999").localeCompare(String(b.dueOn || "9999"))
    );
  });
  return (
    <div className="space-y-5">
      <Panel className="p-5">
        <h2 className="font-semibold text-white">Qué hago ahora</h2>
        <p className="mt-1 text-sm text-slate-500">
          Prioridades reales de Producción, Finanzas y calendario; las tareas
          manuales son el único dato nuevo.
        </p>
        <div className="mt-4 grid gap-3 md:grid-cols-[1fr_auto_auto_auto]">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Añadir tarea manual"
            className="h-10 rounded-xl border border-white/[.08] bg-[#111722] px-3 text-sm text-white"
          />
          <input
            type="date"
            value={dueOn}
            onChange={(e) => setDueOn(e.target.value)}
            className="h-10 rounded-xl border border-white/[.08] bg-[#111722] px-3 text-sm text-white"
          />
          <select
            value={priority}
            onChange={(e) =>
              setPriority(e.target.value as OrganizationTask["priority"])
            }
            className="h-10 rounded-xl border border-white/[.08] bg-[#111722] px-3 text-sm text-white"
          >
            <option value="critical">Crítico</option>
            <option value="today">Hoy</option>
            <option value="upcoming">Próximamente</option>
          </select>
          <button
            disabled={!title.trim() || saving}
            onClick={async () => {
              setSaving(true);
              const ok = await onSave({
                title,
                dueOn: dueOn || null,
                priority,
                notes,
              });
              setSaving(false);
              if (ok) {
                setTitle("");
                setDueOn("");
                setNotes("");
              }
            }}
            className="rounded-xl bg-violet-500 px-4 text-sm font-medium text-white disabled:opacity-40"
          >
            Añadir
          </button>
        </div>
      </Panel>
      <Panel className="p-5">
        <div className="flex items-center justify-between">
          <h2 className="font-semibold text-white">Prioridades</h2>
          <Status tone="violet">{derived.length} abiertas</Status>
        </div>
        <div className="mt-4 space-y-2">
          {derived.map((item) => (
            <div
              key={item.id}
              className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[.07] bg-white/[.02] p-3"
            >
              <div>
                <div className="flex gap-2">
                  <Status
                    tone={
                      item.priority === "critical"
                        ? "red"
                        : item.priority === "today"
                          ? "amber"
                          : "blue"
                    }
                  >
                    {item.priority === "critical"
                      ? "Crítico"
                      : item.priority === "today"
                        ? "Hoy"
                        : "Próximamente"}
                  </Status>
                  <Status tone="violet">{item.source}</Status>
                </div>
                <p className="mt-2 text-sm font-medium text-slate-100">
                  {item.title}
                </p>
                <p className="mt-1 text-xs text-slate-500">
                  {item.dueOn ? formatDate(item.dueOn) : "Sin fecha"}
                </p>
              </div>
              {item.manual && (
                <div className="flex gap-2">
                  <button
                    onClick={() => void onComplete(item.id)}
                    className="rounded-lg border border-emerald-400/25 px-3 py-2 text-xs text-emerald-200"
                  >
                    Hecha
                  </button>
                  <button
                    onClick={() => void onDelete(item.id)}
                    className="rounded-lg border border-rose-400/25 px-3 py-2 text-xs text-rose-200"
                  >
                    Eliminar
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      </Panel>
    </div>
  );
}
function Alert({
  icon: Icon,
  title,
  detail,
  tone,
}: {
  icon: React.ComponentType<{
    className?: string;
  }>;
  title: string;
  detail: string;
  tone: "red" | "amber" | "blue";
}) {
  const styles = {
    red: "bg-rose-400/10 text-rose-300",
    amber: "bg-amber-400/10 text-amber-300",
    blue: "bg-sky-400/10 text-sky-300",
  };
  return (
    <div className="flex gap-3 rounded-xl border border-white/[.05] bg-white/[.018] p-3">
      <span
        className={`grid size-9 shrink-0 place-items-center rounded-xl ${styles[tone]}`}
      >
        <Icon className="size-4" />
      </span>
      <div>
        <p className="text-sm font-medium text-slate-200">{title}</p>
        <p className="mt-1 text-xs text-slate-500">{detail}</p>
      </div>
    </div>
  );
}
function MonthlyChart({
  data,
}: {
  data: {
    month: string;
    income: number;
    expense: number;
  }[];
}) {
  const firstMonth = data[0]?.month;
  const lastMonth = data[data.length - 1]?.month;
  const periodLabel =
    firstMonth && lastMonth
      ? `${firstMonth}–${lastMonth} de ${madridMonthKey().slice(0, 4)}`
      : "Sin movimientos registrados";
  return (
    <Panel className="financial-chart-panel overflow-hidden p-5 sm:p-6">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 className="font-semibold text-white">Ingresos y gastos</h2>
          <p className="mt-1 text-sm text-slate-500">
            {periodLabel} · movimientos registrados
          </p>
        </div>
        <div className="flex items-center gap-3 text-[11px] font-medium">
          <span className="inline-flex items-center gap-1.5 text-emerald-300">
            <i className="size-2 rounded-full bg-emerald-400" /> Ingresos
          </span>
          <span className="inline-flex items-center gap-1.5 text-rose-300">
            <i className="size-2 rounded-full bg-rose-400" /> Gastos
          </span>
        </div>
      </div>
      <div className="mt-5 h-[272px] sm:h-[300px]">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={data}
            margin={{ top: 12, right: 12, bottom: 2, left: 4 }}
            barCategoryGap="26%"
            barGap={5}
          >
            <CartesianGrid vertical={false} stroke="var(--border)" strokeOpacity={0.72} />
            <XAxis
              dataKey="month"
              tickLine={false}
              axisLine={false}
              tick={{ fill: "var(--muted-foreground)", fontSize: 11 }}
              interval={0}
              minTickGap={14}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              width={62}
              tick={{ fill: "var(--muted-foreground)", fontSize: 11 }}
              tickFormatter={(value) =>
                `${Math.round(Number(value) / 1000)}k €`
              }
            />
            <Tooltip
              formatter={(value) => euro.format(number(value))}
              contentStyle={{
                background: "var(--popover)",
                border: "1px solid var(--border)",
                borderRadius: 12,
                boxShadow: "0 18px 44px rgba(0,0,0,.16)",
              }}
              labelStyle={{ color: "var(--foreground)", fontWeight: 700 }}
            />
            <Bar
              dataKey="income"
              name="Ingresos"
              fill="var(--chart-2)"
              radius={[7, 7, 2, 2]}
              maxBarSize={32}
            />
            <Bar
              dataKey="expense"
              name="Gastos"
              fill="var(--destructive)"
              radius={[7, 7, 2, 2]}
              maxBarSize={32}
            />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </Panel>
  );
}
